python -X utf8 -c "
import json,re
seen=set()
for raw in open('C:/Users/echo chamber/.claude/projects/D--/2c300355-703e-4575-81bc-2631a70202cf.jsonl',encoding='utf-8',errors='replace'):
    try: o=json.loads(raw)
    except: continue
    if o.get('type')!='assistant': continue
    m=o.get('message') or {}
    for c in (m.get('content') or []) if isinstance(m.get('content'),list) else []:
        if isinstance(c,dict) and c.get('type')=='tool_use' and c.get('name') in ('Bash','PowerShell'):
            cmd=c['input'].get('command','')
            for x in re.findall(r'[^\n;|&]*\d?>\s*/dev/null[^\n;|&]*', cmd):
                if c['id'] in seen: continue
                print(o.get('timestamp'), '|', x.strip()[:120])
            seen.add(c['id'])
"

